import json
import logging
from functools import cached_property
from time import gmtime


class JsonFormatter(logging.Formatter):
    # see: https://docs.python.org/3.9/howto/logging-cookbook.html#formatting-times-using-utc-gmt-via-configuration
    converter = gmtime  # type: ignore[assignment]

    def __init__(self, datefmt="%Y-%m-%dT%H:%M:%SZ"):
        super().__init__()
        self.datefmt = datefmt

    @cached_property
    def log_record_stdlib_attrs(self) -> dict:
        # to distinguish extras, it's either this or hardcode it from Python docs
        empty_log_record = logging.makeLogRecord({})
        return empty_log_record.__dict__

    def format(self, record: logging.LogRecord) -> str:
        base_msg_dict = {
            # "asctime": self.formatTime(record, self.datefmt),
            "created": record.created,
            "levelname": record.levelname,
            "name": record.name,
            "threadName": record.threadName,
            "message": record.getMessage(),
        }
        # get all the keys that are different between record.__dict and base_log_record_attrs
        extra_keys = record.__dict__.keys() - self.log_record_stdlib_attrs.keys()
        base_msg_dict.update(
            {
                key: record.__dict__.get(key)
                for key in extra_keys
            }
        )

        return json.dumps(base_msg_dict)
